#!/usr/bin/env bash
# BELIAL T3 FIX4 / validated token programs + inherited RPC/WS and AMM v4 + CPMM + CLMM / 12 pools / 90 minutes. PAPER only.
set -euo pipefail
umask 077
if [[ "$#" -gt 1 ]]; then echo "ERRO: use --verificar-pacote, --diagnostico-local ou nenhum argumento." >&2; exit 2; fi
MODE="run"
case "${1:-}" in
  "") ;;
  --verificar-pacote) MODE="verify" ;;
  --diagnostico-local) MODE="audit" ;;
  *) printf 'Uso: bash %s [--verificar-pacote | --diagnostico-local]\n' "$0" >&2; exit 2 ;;
esac
if [[ "$MODE" == run && "${EUID:-$(id -u)}" == 0 ]]; then
  echo 'ERRO: execute como usuário normal, sem sudo/root.' >&2; exit 2
fi
command -v python3 >/dev/null || { echo 'ERRO: Python 3 é necessário.' >&2; exit 2; }
WORK="$(mktemp -d -t belial-t3-90m-fix4-XXXXXX)"
cleanup(){ rm -rf -- "$WORK"; }
trap cleanup EXIT
PAYLOAD_SHA='c81d7a3ea5c31d315d0414e50dc8a5b156574159dfa037291826904e12693b01'
ROOT_NAME='BELIAL_R5D_T3_90M_MP12_FIX4'
python3 - "$0" "$WORK" "$PAYLOAD_SHA" "$ROOT_NAME" <<'PY_EXTRACT'
import base64,hashlib,io,json,sys,tarfile
from pathlib import Path
source,dest,expected,root=sys.argv[1:];dest=Path(dest)
parts=Path(source).read_bytes().split(b'\n__BELIAL_T3_PAYLOAD__\n')
if len(parts)!=2:raise SystemExit('PAYLOAD_MARKER_INVALID')
data=base64.b64decode(b''.join(parts[1].split()),validate=True)
if hashlib.sha256(data).hexdigest()!=expected:raise SystemExit('PAYLOAD_SHA256_MISMATCH')
with tarfile.open(fileobj=io.BytesIO(data),mode='r:gz') as tf:
 seen=set()
 for item in tf.getmembers():
  p=Path(item.name)
  if not item.isfile() or p.is_absolute() or '..' in p.parts or not p.parts or p.parts[0]!=root or item.name in seen:raise SystemExit('PAYLOAD_UNSAFE_MEMBER')
  seen.add(item.name)
  if item.size>64*1024*1024:raise SystemExit('PAYLOAD_FILE_TOO_LARGE')
  target=dest/p;target.parent.mkdir(parents=True,exist_ok=True);target.write_bytes(tf.extractfile(item).read())
folder=dest/root;declared=json.loads((folder/'PAYLOAD_SHA256.json').read_text())['files'];actual={str(p.relative_to(folder)):hashlib.sha256(p.read_bytes()).hexdigest() for p in folder.rglob('*') if p.is_file() and p.name!='PAYLOAD_SHA256.json'}
if declared!=actual:raise SystemExit('PAYLOAD_FILES_MISMATCH')
print('BELIAL_T3_PAYLOAD_SHA256_OK=true',flush=True)
print('BELIAL_T3_FILES_VERIFIED='+str(len(actual)),flush=True)
PY_EXTRACT
export PYTHONDONTWRITEBYTECODE=1 PYTHONNOUSERSITE=1
if [[ "$MODE" == verify ]]; then
 python3 -B - "$WORK/$ROOT_NAME" <<'PY_VERIFY'
import subprocess,sys
from pathlib import Path
root=Path(sys.argv[1])
for group in ('mp12','n2_mp12','d2','runner','perp'):
 print('\nVALIDANDO '+group,flush=True)
 subprocess.run([sys.executable,'-B','-m','unittest','discover','-s',str(root/group/'tests'),'-v'],check=True)
print('BELIAL_T3_PACKAGE_TESTS_OK=true')
print('CAPTURE_TARGET_MINUTES=90; CAPTURE_TARGET_SECONDS=5400')
print('CAPTURE_STARTED=false; INSTALLED=false; TRANSACTIONS_SUBMITTED=false')
PY_VERIFY
elif [[ "$MODE" == audit ]]; then
 python3 -B "$WORK/$ROOT_NAME/runner/tools/audit_saved_tokens.py"
 printf "CAPTURE_STARTED=false; INSTALLED=false; NETWORK_REQUESTED=false\n"
else
 python3 -B "$WORK/$ROOT_NAME/runner/tools/install_and_run.py" --payload "$WORK/$ROOT_NAME"
fi
exit 0
